-- Load data/evidence.json into Zetaris as a governed view the agent queries (run in the Zetaris SQL editor after install).
CREATE SCHEMA IF NOT EXISTS why_agent;
CREATE TABLE IF NOT EXISTS why_agent.evidence (id VARCHAR, fact VARCHAR, source VARCHAR, date VARCHAR, tags VARCHAR);
-- INSERT rows generated by: python3 -c "import json;[print(f\"INSERT INTO why_agent.evidence VALUES ('{e['id']}','{e['fact'].replace(chr(39),chr(39)*2)}','{e['source']}','{e['date']}','{','.join(e['tags'])}');\") for e in json.load(open('data/evidence.json'))]"
